CREATE INDEX "entitlement_states_due_idx" ON "entitlement_states" USING btree ("valid_until") WHERE "entitlement_states"."valid_until" is not null;--> statement-breakpoint
ALTER TABLE "agreement_amendments" ADD CONSTRAINT "agreement_amendments_four_eyes" CHECK (("agreement_amendments"."status" <> 'approved' or (("agreement_amendments"."authored_by" is null or "agreement_amendments"."decided_by" is distinct from "agreement_amendments"."authored_by") and ("agreement_amendments"."authored_by_operator" is null or "agreement_amendments"."decided_by_operator" is null or lower(btrim("agreement_amendments"."decided_by_operator")) <> lower(btrim("agreement_amendments"."authored_by_operator"))))) is true);